package com.elis.lila;
import android.app.*;import android.os.*;import android.media.*;import android.graphics.Color;import android.view.*;import android.widget.*;
public class AlarmActivity extends Activity {
 MediaPlayer player;Vibrator vibrator;
 @Override public void onCreate(Bundle b){super.onCreate(b);setShowWhenLocked(true);setTurnScreenOn(true);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setGravity(Gravity.CENTER);root.setPadding(30,30,30,30);root.setBackgroundColor(Color.rgb(245,238,255));TextView text=new TextView(this);text.setText("⏰ Ders zamanı!\n\n"+getIntent().getStringExtra("title"));text.setTextSize(28);text.setGravity(Gravity.CENTER);root.addView(text);Button stop=new Button(this);stop.setText("ALARMI DURDUR");root.addView(stop);stop.setOnClickListener(v->finish());setContentView(root);try{android.net.Uri uri=RingtoneManager.getDefaultUri(RingtoneManager.TYPE_ALARM);if(uri==null)uri=RingtoneManager.getDefaultUri(RingtoneManager.TYPE_NOTIFICATION);player=MediaPlayer.create(this,uri);if(player!=null){player.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ALARM).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build());player.setLooping(true);player.start();}}catch(Exception ignored){}vibrator=(Vibrator)getSystemService(VIBRATOR_SERVICE);if(vibrator!=null&&vibrator.hasVibrator())vibrator.vibrate(VibrationEffect.createWaveform(new long[]{0,500,300,500},0));}
 @Override protected void onDestroy(){if(player!=null){player.stop();player.release();}if(vibrator!=null)vibrator.cancel();super.onDestroy();}
}